INSERT INTO `generated_report` VALUES (1,1,15,'A-01井标准测井分析报告','{\"endDate\": \"2024-01-31\", \"wellName\": \"A-01\", \"startDate\": \"2024-01-01\", \"curveTypes\": [\"GR\", \"SP\", \"RES\"], \"depthRange\": {\"max\": 3000, \"min\": 0}, \"templateId\": 1, \"datasetName\": \"2024年1月测井数据\", \"analysisType\": \"standard\"}','# A-01井标准测井分析报告\r\n\r\n ## 报告基本信息\r\n - **井名**: A-01\r\n - **数据集**: 2024年1月测井数据\r\n - **分析类型**: 标准分析\r\n - **生成时间**: 2024-01-20 15:30:00\r\n - **分析人员**: 张工程师\r\n\r\n ## 数据概况\r\n - **深度范围**: 0m - 3000m\r\n - **曲线类型**: GR, SP, RES\r\n - **数据点数**: 1250个\r\n\r\n ## 主要分析结果\r\n\r\n ### 1. 地层特征分析\r\n 根据测井数据分析，该井段主要发育以下地层：\r\n - 泥岩层：厚度约占35%，自然伽马值较高\r\n - 砂岩层：厚度约占45%，电阻率相对较低\r\n - 碳酸盐岩：厚度约占20%，密度值偏高\r\n\r\n ### 2. 物性参数\r\n - **平均孔隙度**: 15.2%\r\n - **平均渗透率**: 85.6mD\r\n - **含水饱和度**: 32.4%\r\n\r\n ### 3. 含油气性评价\r\n - **油层识别**: 发现2个潜在油层\r\n - **气层识别**: 发现1个潜在气层\r\n - **水层识别**: 主要为边底水层\r\n\r\n ## 结论与建议\r\n 1. 该井段具有良好的勘探前景\r\n 2. 建议在2500米深度进行试油作业\r\n 3. 需要进一步进行流体取样分析\r\n\r\n ---\r\n *报告生成时间: 2024-01-20 15:30:00*\r\n *模板版本: 标准测井分析报告 v1.0*','/reports/A-01_standard_analysis_20240120.md',18,1,'2024-01-20 15:25:00','2024-01-20 15:30:00'),(2,2,15,'B-02井岩石物理分析报告','{\"endDate\": \"2024-01-25\", \"wellName\": \"B-02\", \"startDate\": \"2024-01-15\", \"curveTypes\": [\"GR\", \"DEN\", \"CNL\", \"AC\"], \"depthRange\": {\"max\": 2800, \"min\": 1200}, \"templateId\": 2, \"datasetName\": \"rock_physics_dataset\", \"analysisType\": \"technical\"}','# B-02井岩石物理分析报告\r\n\r\n ## 岩石物理参数计算\r\n\r\n ### 1.1 孔隙度分析\r\n - 密度孔隙度：18.5%\r\n - 声波孔隙度：16.8%\r\n - 中子孔隙度：19.2%\r\n - 平均孔隙度：18.2%\r\n\r\n ### 1.2 渗透率估算\r\n - Wyllie模型：120.5 mD\r\n - Coates模型：95.3 mD\r\n - 平均渗透率：107.9 mD\r\n\r\n ### 1.3 饱和度计算\r\n - 含水饱和度：28.6%\r\n - 含油饱和度：62.1%\r\n - 含气饱和度：9.3%\r\n\r\n ## 2. 流体识别\r\n 通过交会图分析，识别出：\r\n - 油层段：1800-2200m，Sw=25-35%\r\n - 气层段：2400-2600m，Sg=15-25%\r\n - 水层段：底部2700-2800m，Sw>80%\r\n\r\n ## 3. 岩性解释\r\n - 砂岩：1500-2300m，φ>15%\r\n - 泥岩：顶部0-1500m，GR>100API\r\n - 碳酸盐岩：2600-2800m，DEN>2.6g/cm³\r\n\r\n ## 4. 储层评价\r\n 优质储层：1800-2200m，φ>18%，K>100mD\r\n 中等储层：2200-2600m，φ=12-18%，K=50-100mD\r\n 差质储层：其他层段\r\n\r\n ---\r\n *分析时间：2024-01-20 16:45:00*\r\n *计算方法：岩石物理建模*','/reports/B-02_rock_physics_20240120.pdf',8,1,'2024-01-20 16:30:00','2024-01-20 16:45:00'),(3,3,15,'C-03井综合地质评价报告','{\"endDate\": \"2024-02-10\", \"wellName\": \"C-03\", \"startDate\": \"2024-01-10\", \"curveTypes\": [\"GR\", \"SP\", \"RES\", \"CAL\", \"AC\", \"CNL\", \"DEN\"], \"depthRange\": {\"max\": 3500, \"min\": 800}, \"templateId\": 3, \"datasetName\": \"comprehensive_evaluation\", \"analysisType\": \"comprehensive\"}','# C-03井综合地质评价报告\r\n\r\n ## 1. 区域地质背景\r\n 该井位于XX盆地中央隆起带，构造位置优越，具备良好生储盖组合。\r\n\r\n ## 2. 构造特征\r\n - 构造形态：背斜构造\r\n - 闭合高度：150米\r\n - 圈闭面积：2.5km²\r\n - 断层发育：较少，构造相对完整\r\n\r\n ## 3. 沉积相分析\r\n - 沉积环境：三角洲前缘亚相\r\n - 主要岩性：中细砂岩、粉砂岩\r\n - 沉积韵律：反旋回为主\r\n - 储层分布：多期河道叠置\r\n\r\n ## 4. 储层评价\r\n\r\n ### 4.1 储层物性\r\n - 有效厚度：185米\r\n - 平均孔隙度：16.8%\r\n - 平均渗透率：156.3mD\r\n - 孔隙结构：中等偏好\r\n\r\n ### 4.2 含油气性\r\n - 含油饱和度：65.2%\r\n - 含气饱和度：12.3%\r\n - 含水饱和度：22.5%\r\n - 流体性质：轻质油\r\n\r\n ### 4.3 储层分类\r\n - Ⅰ类储层：1200-1800m，优质储层\r\n - Ⅱ类储层：1800-2800m，中等储层\r\n - Ⅲ类储层：其他层段，较差储层\r\n\r\n ## 5. 钻井建议\r\n - 推荐井型：水平井\r\n - 靶点深度：1500-1700m\r\n - 完井方式：裸眼完井\r\n - 压裂改造：建议实施\r\n\r\n ## 6. 风险评估\r\n - 地质风险：中等偏低\r\n - 工程风险：可控\r\n - 经济风险：投资回报率预计>15%\r\n\r\n ---\r\n *评价时间：2024-01-21 10:30:00*\r\n *评价人员：李地质师*','/reports/C-03_comprehensive_20240121.docx',12,1,'2024-01-21 09:15:00','2024-01-21 10:30:00'),(7,1,15,'A-01井标准测井分析报告','{\"endDate\": \"2024-01-31\", \"wellName\": \"A-01\", \"startDate\": \"2024-01-01\", \"curveTypes\": [\"GR\", \"SP\", \"RES\"], \"depthRange\": {\"max\": 3000, \"min\": 0}, \"templateId\": 1, \"datasetName\": \"2024年1月测井数据\", \"analysisType\": \"standard\"}','# A-01井标准测井分析报告\r\n\r\n ## 报告基本信息\r\n - **井名**: A-01\r\n - **数据集**: 2024年1月测井数据\r\n - **分析类型**: 标准分析\r\n - **生成时间**: 2024-01-20 15:30:00\r\n - **分析人员**: 张工程师\r\n\r\n ## 数据概况\r\n - **深度范围**: 0m - 3000m\r\n - **曲线类型**: GR, SP, RES\r\n - **数据点数**: 1250个\r\n\r\n ## 主要分析结果\r\n\r\n ### 1. 地层特征分析\r\n 根据测井数据分析，该井段主要发育以下地层：\r\n - 泥岩层：厚度约占35%，自然伽马值较高\r\n - 砂岩层：厚度约占45%，电阻率相对较低\r\n - 碳酸盐岩：厚度约占20%，密度值偏高\r\n\r\n ### 2. 物性参数\r\n - **平均孔隙度**: 15.2%\r\n - **平均渗透率**: 85.6mD\r\n - **含水饱和度**: 32.4%\r\n\r\n ### 3. 含油气性评价\r\n - **油层识别**: 发现2个潜在油层\r\n - **气层识别**: 发现1个潜在气层\r\n - **水层识别**: 主要为边底水层\r\n\r\n ## 结论与建议\r\n 1. 该井段具有良好的勘探前景\r\n 2. 建议在2500米深度进行试油作业\r\n 3. 需要进一步进行流体取样分析\r\n\r\n ---\r\n *报告生成时间: 2024-01-20 15:30:00*\r\n *模板版本: 标准测井分析报告 v1.0*','/reports/A-01_standard_analysis_20240120.md',15,1,'2024-01-20 15:25:00','2024-01-20 15:30:00'),(8,2,15,'B-02井岩石物理分析报告','{\"endDate\": \"2024-01-25\", \"wellName\": \"B-02\", \"startDate\": \"2024-01-15\", \"curveTypes\": [\"GR\", \"DEN\", \"CNL\", \"AC\"], \"depthRange\": {\"max\": 2800, \"min\": 1200}, \"templateId\": 2, \"datasetName\": \"rock_physics_dataset\", \"analysisType\": \"technical\"}','# B-02井岩石物理分析报告\r\n\r\n ## 岩石物理参数计算\r\n\r\n ### 1.1 孔隙度分析\r\n - 密度孔隙度：18.5%\r\n - 声波孔隙度：16.8%\r\n - 中子孔隙度：19.2%\r\n - 平均孔隙度：18.2%\r\n\r\n ### 1.2 渗透率估算\r\n - Wyllie模型：120.5 mD\r\n - Coates模型：95.3 mD\r\n - 平均渗透率：107.9 mD\r\n\r\n ### 1.3 饱和度计算\r\n - 含水饱和度：28.6%\r\n - 含油饱和度：62.1%\r\n - 含气饱和度：9.3%\r\n\r\n ## 2. 流体识别\r\n 通过交会图分析，识别出：\r\n - 油层段：1800-2200m，Sw=25-35%\r\n - 气层段：2400-2600m，Sg=15-25%\r\n - 水层段：底部2700-2800m，Sw>80%\r\n\r\n ## 3. 岩性解释\r\n - 砂岩：1500-2300m，φ>15%\r\n - 泥岩：顶部0-1500m，GR>100API\r\n - 碳酸盐岩：2600-2800m，DEN>2.6g/cm³\r\n\r\n ## 4. 储层评价\r\n 优质储层：1800-2200m，φ>18%，K>100mD\r\n 中等储层：2200-2600m，φ=12-18%，K=50-100mD\r\n 差质储层：其他层段\r\n\r\n ---\r\n *分析时间：2024-01-20 16:45:00*\r\n *计算方法：岩石物理建模*','/reports/B-02_rock_physics_20240120.pdf',8,1,'2024-01-20 16:30:00','2024-01-20 16:45:00'),(9,3,15,'C-03井综合地质评价报告','{\"endDate\": \"2024-02-10\", \"wellName\": \"C-03\", \"startDate\": \"2024-01-10\", \"curveTypes\": [\"GR\", \"SP\", \"RES\", \"CAL\", \"AC\", \"CNL\", \"DEN\"], \"depthRange\": {\"max\": 3500, \"min\": 800}, \"templateId\": 3, \"datasetName\": \"comprehensive_evaluation\", \"analysisType\": \"comprehensive\"}','# C-03井综合地质评价报告\r\n\r\n ## 1. 区域地质背景\r\n 该井位于XX盆地中央隆起带，构造位置优越，具备良好生储盖组合。\r\n\r\n ## 2. 构造特征\r\n - 构造形态：背斜构造\r\n - 闭合高度：150米\r\n - 圈闭面积：2.5km²\r\n - 断层发育：较少，构造相对完整\r\n\r\n ## 3. 沉积相分析\r\n - 沉积环境：三角洲前缘亚相\r\n - 主要岩性：中细砂岩、粉砂岩\r\n - 沉积韵律：反旋回为主\r\n - 储层分布：多期河道叠置\r\n\r\n ## 4. 储层评价\r\n\r\n ### 4.1 储层物性\r\n - 有效厚度：185米\r\n - 平均孔隙度：16.8%\r\n - 平均渗透率：156.3mD\r\n - 孔隙结构：中等偏好\r\n\r\n ### 4.2 含油气性\r\n - 含油饱和度：65.2%\r\n - 含气饱和度：12.3%\r\n - 含水饱和度：22.5%\r\n - 流体性质：轻质油\r\n\r\n ### 4.3 储层分类\r\n - Ⅰ类储层：1200-1800m，优质储层\r\n - Ⅱ类储层：1800-2800m，中等储层\r\n - Ⅲ类储层：其他层段，较差储层\r\n\r\n ## 5. 钻井建议\r\n - 推荐井型：水平井\r\n - 靶点深度：1500-1700m\r\n - 完井方式：裸眼完井\r\n - 压裂改造：建议实施\r\n\r\n ## 6. 风险评估\r\n - 地质风险：中等偏低\r\n - 工程风险：可控\r\n - 经济风险：投资回报率预计>15%\r\n\r\n ---\r\n *评价时间：2024-01-21 10:30:00*\r\n *评价人员：李地质师*','/reports/C-03_comprehensive_20240121.docx',12,1,'2024-01-21 09:15:00','2024-01-21 10:30:00'),(10,1,15,'D-04井分析报告','{\"wellName\": \"D-04\", \"templateId\": 1, \"datasetName\": \"ongoing_dataset\"}','# D-04井分析报告（生成中）',NULL,0,0,'2024-01-21 14:20:00',NULL),(11,2,15,'E-05井岩石物理分析','{\"wellName\": \"E-05\", \"templateId\": 2, \"datasetName\": \"failed_dataset\"}','# E-05井岩石物理分析（生成失败）\r\n 错误原因：数据质量不满足分析要求，缺失关键曲线数据。',NULL,0,2,'2024-01-21 15:30:00','2024-01-21 15:35:00'),(12,1,15,'F-06井标准分析报告','{\"wellName\": \"F-06\", \"templateId\": 1, \"datasetName\": \"popular_dataset\"}','# F-06井标准分析报告\r\n （此处为详细分析内容...）','/reports/F-06_popular_20240121.md',45,1,'2024-01-19 11:15:00','2024-01-19 11:20:00'),(13,1,15,'ss_标准测井分析报告','{\"endDate\": \"2026-02-11\", \"depthEnd\": 0.6, \"wellName\": \"ss\", \"startDate\": \"2026-01-25\", \"curveTypes\": [\"SP\", \"GR\", \"RES\", \"CAL\", \"AC\", \"CNL\", \"DEN\"], \"depthStart\": 0, \"templateId\": 1, \"datasetName\": \"dataset-2026-2\", \"reportTitle\": \"ss_标准测井分析报告\", \"analysisType\": \"standard\", \"previewContent\": \"# 标准测井分析报告\\r\\n\\r\\n                                                                                                                            ## 1. 基本信息\\r\\n                                                                                                                            - 井名：ss\\r\\n                                                                                                                            - 数据集：dataset-2026-2\\r\\n                                                                                                                            - 分析时间：{{analysisTime}}\\r\\n                                                                                                                            - 分析人员：{{analyst}}\\r\\n\\r\\n                                                                                                                            ## 2. 数据概览\\r\\n                                                                                                                            - 数据点数：{{dataPoints}}\\r\\n                                                                                                                            - 深度范围：{{depthMin}}m - {{depthMax}}m\\r\\n                                                                                                                            - 曲线类型：[SP, GR, RES, CAL, AC, CNL, DEN]\\r\\n\\r\\n                                                                                                                            ## 3. 质量评估\\r\\n                                                                                                                            - 数据完整性：{{dataQuality}}%\\r\\n                                                                                                                            - 有效数据段：{{validSections}}\\r\\n                                                                                                                            - 异常值数量：{{anomalyCount}}\\r\\n\\r\\n                                                                                                                            ## 4. 主要发现\\r\\n            