--
-- Table structure for table `log_data`
--

DROP TABLE IF EXISTS `log_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `log_data` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '数据ID（主键）',
  `user_id` int unsigned NOT NULL COMMENT '关联用户表ID',
  `dataset_name` varchar(50) NOT NULL COMMENT '数据集名（如：dataset-2026）',
  `well_name` varchar(50) NOT NULL COMMENT '井名',
  `depth` decimal(10,2) NOT NULL COMMENT '深度（单位：m）',
  `ac` decimal(15,6) DEFAULT NULL COMMENT '声波时差（AC）',
  `cal` decimal(15,6) DEFAULT NULL COMMENT '井径（CAL）',
  `gr` decimal(15,6) DEFAULT NULL COMMENT '自然伽马（GR）',
  `den` decimal(15,6) DEFAULT NULL COMMENT '密度（DEN）',
  `rt` decimal(15,6) DEFAULT NULL COMMENT '深电阻率（RT）',
  `rxo` decimal(15,6) DEFAULT NULL COMMENT '浅电阻率（RXO）',
  `is_original` tinyint NOT NULL DEFAULT '1' COMMENT '是否原始数据：1-是，0-预测数据',
  `confidence` decimal(5,4) DEFAULT NULL COMMENT '预测置信度（仅预测数据有效）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_dataset_well_depth` (`user_id`,`dataset_name`,`well_name`,`depth`) COMMENT '唯一约束：同一用户+数据集+井名+深度仅一条记录',
  KEY `idx_user_id` (`user_id`),
  KEY `idx_dataset_well` (`dataset_name`,`well_name`) COMMENT '按数据集+井名快速查询',
  KEY `idx_depth` (`depth`) COMMENT '按深度范围查询',
  CONSTRAINT `log_data_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=596 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='测井数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

