--
-- Table structure for table `notification`
--

DROP TABLE IF EXISTS `notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '通知ID（主键）',
  `user_id` int unsigned NOT NULL COMMENT '关联用户表ID',
  `title` varchar(100) NOT NULL COMMENT '通知标题',
  `type` varchar(20) NOT NULL COMMENT '通知类型：system/warning/task',
  `content` text NOT NULL COMMENT '通知内容',
  `status` varchar(10) NOT NULL DEFAULT 'unread' COMMENT '状态：unread(未读)/read(已读)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id_status` (`user_id`,`status`) COMMENT '按用户ID+状态查询（高频查询）',
  KEY `idx_user_id_type` (`user_id`,`type`) COMMENT '按用户ID+类型查询',
  KEY `idx_user_id_create_time` (`user_id`,`create_time` DESC) COMMENT '按用户ID+创建时间排序查询',
  CONSTRAINT `notification_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户通知表';
/*!40101 SET character_set_client = @saved_cs_client */;

