INSERT INTO `notification` VALUES (1,15,'系统例行维护通知','system','系统将于2026-02-05 23:00-24:00进行例行维护，维护期间部分功能将暂时不可用，给你带来不便敬请谅解！','unread','2026-02-02 15:30:00','2026-02-03 16:20:52'),(2,15,'系统版本更新提醒','system','测井数据管理系统已完成V2.1版本更新，新增数据批量导入、预测结果可视化功能，欢迎体验！','unread','2026-02-01 10:00:00','2026-02-03 16:20:51'),(3,15,'数据库备份完成通知','system','2026-01-31 02:00数据库自动备份完成，备份文件已存储至云服务器，备份有效期7天。','unread','2026-01-31 02:30:00','2026-02-03 16:20:52'),(4,15,'数据导入失败警告','warning','你于2026-02-02 14:10提交的「dataset-2026-02」数据集导入失败，原因：文件格式错误（请使用CSV格式），请重新上传！','unread','2026-02-02 14:15:00','2026-02-03 16:20:51'),(5,15,'账号异地登录提醒','warning','你的账号于2026-02-01 08:45在「北京市」异地登录，若非本人操作，请立即修改密码！','unread','2026-02-01 08:50:00','2026-02-01 08:50:00'),(6,15,'磁盘空间不足警告','warning','服务器磁盘剩余空间不足20%，请及时清理无用数据，避免影响测井数据预测功能正常运行。','unread','2026-01-30 16:20:00','2026-02-03 16:20:51'),(7,15,'测井数据预测任务完成','task','你于2026-02-02 10:00提交的「井名：J101，深度：1-1000m」CNL预测任务已完成，可前往「预测历史」查看结果！','unread','2026-02-02 11:30:00','2026-02-03 16:20:51'),(8,15,'数据审核任务待处理','task','你提交的「dataset-2026-01」数据集已进入审核阶段，预计1个工作日内完成审核，请注意查看审核结果。','unread','2026-02-01 16:00:00','2026-02-03 16:20:51'),(9,15,'测井数据导出任务完成','task','你于2026-01-31 15:00提交的「J102井」测井数据导出任务已完成，可前往「数据管理」下载文件。','unread','2026-01-31 15:10:00','2026-02-03 16:20:51'),(10,15,'预测模型训练任务完成','task','自定义测井数据预测模型训练完成，模型准确率92.5%，可前往「模型管理」绑定使用。','unread','2026-01-30 09:40:00','2026-02-03 16:20:51'),(11,15,'新功能使用指引','system','系统新增「测井数据对比分析」功能，可在「数据分析」模块使用，点击查看详细使用教程：http://xxx.xxx.xxx/guide','read','2026-02-02 16:00:00','2026-02-03 16:21:10'),(12,15,'预测任务执行超时提醒','warning','你于2026-02-02 09:00提交的预测任务执行超时，建议检查输入数据是否完整后重新提交。','unread','2026-02-02 09:30:00','2026-02-03 16:20:51'),(13,15,'数据集共享成功通知','task','你已成功将「dataset-2026-02」共享给用户「test_user」，对方可在「共享数据」中查看。','unread','2026-02-02 12:00:00','2026-02-03 16:20:51'),(14,15,'密码即将过期提醒','system','你的账号密码将于2026-02-10过期，请及时前往「个人中心」修改密码，避免影响使用。','unread','2026-02-02 10:30:00','2026-02-03 16:20:51'),(15,15,'测井数据异常提醒','warning','检测到「J103井」深度500-600m的GR数据存在异常波动，建议核对原始数据后修正。','unread','2026-02-01 14:00:00','2026-02-03 16:20:51'),(16,12,'欢迎使用测井数据管理系统','system','恭喜你成功注册测井数据管理系统，新用户可免费体验所有功能30天，快来开始使用吧！','unread','2026-02-02 17:00:00','2026-02-02 17:00:00'),(17,12,'首次预测任务指引','task','点击「预测管理」-「新建任务」，即可开始测井数据CNL预测，支持多参数联合输入。','unread','2026-02-02 17:05:00','2026-02-02 17:05:00'),(18,15,'系统维护通知','system','计划于本周六凌晨2:00-4:00进行系统升级维护，期间测井数据服务可能暂时中断，请提前保存工作内容。','read','2026-01-29 22:00:26','2026-02-03 22:00:26'),(19,15,'dataset-2026-1数据导入完成','task','您导入的Well-A1井测井数据（dataset-2026-1，深度段2100-2120m）已完成质量检查，共导入24条记录，数据完整性100%。','read','2026-01-31 22:00:26','2026-02-03 22:00:26'),(20,15,'dataset-2026-2数据导入完成','task','您导入的Well-B2井测井数据（dataset-2026-2，深度段1850-1872m）已完成质量检查，共导入23条记录，数据完整性100%。','read','2026-01-31 22:00:26','2026-02-03 22:00:26'),(21,15,'CNL预测任务执行成功 - Well-A1','task','数据集：dataset-2026-1，井名：Well-A1，深度段：2121-2123m的CNL预测任务已完成，平均置信度95.4%，请查看预测结果。','unread','2026-02-02 22:00:26','2026-02-03 22:00:26'),(22,15,'CNL预测任务执行成功 - Well-C3','task','数据集：dataset-2026-3，井名：Well-C3，深度段：1971-1972m的CNL预测任务已完成，平均置信度96.1%，请查看预测结果。','unread','2026-02-03 12:00:26','2026-02-03 22:00:26'),(23,15,'数据质量警告 - dataset-2026-2','warning','Well-B2井（dataset-2026-2）在深度1864-1866m处检测到井径异常扩大（CAL>10.5in），可能影响密度曲线精度，建议进行井眼校正处理。','unread','2026-02-01 22:00:26','2026-02-03 22:00:26'),(24,15,'数据质量警告 - dataset-2026-4','warning','Well-D4井（dataset-2026-4）在2204-2205m和2211-2212m处检测到薄互层特征，建议提高采样率或进行曲线平滑处理。','unread','2026-02-02 22:00:26','2026-02-03 22:00:26'),(25,15,'存储空间提醒','system','您的测井数据存储空间已使用82%，建议清理历史预测数据或联系管理员扩容。','unread','2026-02-03 10:00:26','2026-02-03 22:00:26'),(26,15,'Well-B2井低阻层识别','warning','数据集dataset-2026-2的Well-B2井1850-1870m深度段识别出低阻特征（RT<3Ω·m），结合AC、DEN响应特征，初步判断为水层，建议结合试油资料验证。','unread','2026-02-03 16:00:26','2026-02-03 22:00:26'),(27,15,'Well-C3井高阻层识别','warning','数据集dataset-2026-3的Well-C3井1950-1970m深度段识别出高阻特征（RT>350Ω·m），结合低DEN（2.32-2.39）特征，初步判断为气层，建议重点关注。','unread','2026-02-03 18:00:26','2026-02-03 22:00:26');
