--
-- Table structure for table `prediction_history`
--

DROP TABLE IF EXISTS `prediction_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prediction_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL COMMENT '关联用户表ID',
  `dataset_name` varchar(50) NOT NULL COMMENT '数据集名（如：dataset-2026）',
  `well_name` varchar(50) NOT NULL COMMENT '井名',
  `depth_range` varchar(50) NOT NULL COMMENT '深度范围（如：1-1000m）',
  `input_prediction_data` json DEFAULT NULL COMMENT '输入的预测数据（JSON格式，存储AC/CAL/GR等输入参数）',
  `cnl_prediction` decimal(15,6) DEFAULT NULL COMMENT 'CNL（中子孔隙度）预测结果',
  `status` varchar(20) NOT NULL COMMENT '预测状态：success/processing/error',
  `error_message` varchar(512) DEFAULT '' COMMENT '错误信息（如有）',
  `execution_time` bigint DEFAULT NULL COMMENT '执行耗时(毫秒)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_dataset_well` (`dataset_name`,`well_name`) COMMENT '按数据集+井名快速查询',
  KEY `idx_status_create_time` (`status`,`create_time`) COMMENT '按状态+时间筛选',
  CONSTRAINT `prediction_history_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户预测历史记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `prediction_history`
--

LOCK TABLES `prediction_history` WRITE;
/*!40000 ALTER TABLE `prediction_history` DISABLE KEYS */;
