-- Table structure for table `report_template`
--

DROP TABLE IF EXISTS `report_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `report_template` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `user_id` int unsigned NOT NULL COMMENT '创建用户ID',
  `name` varchar(100) NOT NULL COMMENT '模板名称',
  `description` text COMMENT '模板描述',
  `category` varchar(20) NOT NULL COMMENT '分类：basic/basic_technical/comprehensive/custom',
  `documentUrl` varchar(255) NOT NULL COMMENT '模板文档URL地址',
  `variables` json DEFAULT NULL COMMENT '模板变量定义',
  `is_public` tinyint NOT NULL DEFAULT '0' COMMENT '是否公开：0-私有，1-公开',
  `usage_count` int NOT NULL DEFAULT '0' COMMENT '使用次数',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0-禁用，1-启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_template_category` (`category`),
  KEY `idx_template_user_id` (`user_id`),
  KEY `idx_template_public` (`is_public`),
  KEY `idx_template_status` (`status`),
  CONSTRAINT `fk_template_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='报告模板表';
/*!40101 SET character_set_client = @saved_cs_client */;

