INSERT INTO `report_template` VALUES (1,15,'标准测井分析报告','包含基础测井数据分析的标准报告模板，适用于常规井况评估','basic','t93w5m2o3.hd-bkt.clouddn.com/fa57eb04-89e9-4536-a1c9-8f262bc2eeb4.pdf','{\"analyst\": \"string\", \"depthMax\": \"number\", \"depthMin\": \"number\", \"wellName\": \"string\", \"curveTypes\": \"array\", \"dataPoints\": \"number\", \"conclusions\": \"text\", \"dataQuality\": \"number\", \"datasetName\": \"string\", \"analysisTime\": \"datetime\", \"anomalyCount\": \"number\", \"mainFindings\": \"text\", \"generatedTime\": \"datetime\", \"validSections\": \"number\"}',1,9,1,'2026-02-09 14:52:51','2026-02-10 11:56:03'),(2,15,'岩石物理分析报告','专业的岩石物理参数分析报告模板，包含详细的岩石物性计算','technical','t93w5m2o3.hd-bkt.clouddn.com/fa57eb04-89e9-4536-a1c9-8f262bc2eeb4.pdf','{\"analysisTime\": \"datetime\", \"gasSaturation\": \"number\", \"oilSaturation\": \"number\", \"sonicPorosity\": \"number\", \"averagePorosity\": \"number\", \"densityPorosity\": \"number\", \"neutronPorosity\": \"number\", \"waterSaturation\": \"number\", \"calculationMethod\": \"string\", \"coatesPermeability\": \"number\", \"wylliePermeability\": \"number\", \"averagePermeability\": \"number\", \"fluidIdentification\": \"text\", \"reservoirEvaluation\": \"text\", \"lithologyInterpretation\": \"text\"}',1,1,1,'2026-02-09 14:52:51','2026-02-10 12:24:34'),(3,15,'综合地质评价报告','全面的地质评价报告模板，涵盖构造、沉积、储层等多个方面','comprehensive','t93w5m2o3.hd-bkt.clouddn.com/fa57eb04-89e9-4536-a1c9-8f262bc2eeb4.pdf','{\"evaluator\": \"string\", \"evaluationTime\": \"datetime\", \"riskAssessment\": \"text\", \"regionalGeology\": \"text\", \"structuralFeatures\": \"text\", \"reservoirProperties\": \"text\", \"sedimentaryAnalysis\": \"text\", \"hydrocarbonPotential\": \"text\", \"drillingRecommendations\": \"text\", \"reservoirClassification\": \"text\"}',1,0,1,'2026-02-09 14:52:51','2026-02-09 22:18:52'),(4,15,'测井曲线质量检查报告','专门用于测井曲线质量检查和问题诊断的报告模板','specialized','t93w5m2o3.hd-bkt.clouddn.com/fa57eb04-89e9-4536-a1c9-8f262bc2eeb4.pdf','{\"checkId\": \"string\", \"checker\": \"string\", \"wellName\": \"string\", \"checkDate\": \"date\", \"checkTime\": \"datetime\", \"datasetName\": \"string\", \"denAccuracy\": \"number\", \"grAnomalies\": \"number\", \"grContinuity\": \"number\", \"grCalibration\": \"string\", \"problemSummary\": \"text\", \"resConsistency\": \"string\", \"denQualityGrade\": \"string\", \"followUpActions\": \"text\", \"resCompleteness\": \"number\", \"resReasonableness\": \"string\", \"handlingSuggestions\": \"text\", \"denEnvironmentEffect\": \"string\"}',0,0,1,'2026-02-09 14:52:51','2026-02-09 22:18:52'),(5,15,'产能预测分析报告','基于测井数据的产能预测和经济评价报告模板','technical','t93w5m2o3.technical-bkt.clouddn.com/fa57eb04-89e9-4536-a1c9-8f262bc2eeb4.pdf','{\"wellName\": \"string\", \"predictionTime\": \"datetime\", \"flowCoefficient\": \"number\", \"predictionMethod\": \"string\", \"annualOutputValue\": \"number\", \"formationPressure\": \"number\", \"productivityIndex\": \"number\", \"dailyGasProduction\": \"number\", \"dailyOilProduction\": \"number\", \"formationTemperature\": \"number\", \"productivityEquation\": \"string\", \"absoluteOpenFlowActual\": \"number\", \"investmentPaybackPeriod\": \"number\", \"bottomholeFlowingPressure\": \"number\", \"developmentRecommendations\": \"text\", \"absoluteOpenFlowTheoretical\": \"number\"}',1,0,1,'2026-02-09 14:52:51','2026-02-09 23:17:59'),(12,15,'564','525','technical','t93w5m2o3.technical-bkt.clouddn.com/fa57eb04-89e9-4536-a1c9-8f262bc2eeb4.pdf',NULL,0,0,0,'2026-02-09 23:17:59','2026-02-09 23:26:53');
