DROP TABLE IF EXISTS `todotask`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `todotask` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int unsigned NOT NULL COMMENT '用户ID',
  `title` varchar(100) NOT NULL COMMENT '待办标题',
  `content` text COMMENT '详细内容',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0-待完成，1-已完成，2-已取消',
  `priority` tinyint NOT NULL DEFAULT '1' COMMENT '优先级：0-低，1-中，2-高',
  `due_date` datetime DEFAULT NULL COMMENT '截止日期',
  `category` varchar(20) DEFAULT '' COMMENT '分类标签（如 “测井数据检查”“曲线重构”“模型优化” 等行业分类）',
  `finish_time` datetime DEFAULT NULL COMMENT '完成时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_todo_user_id` (`user_id`),
  KEY `idx_todo_status` (`status`),
  KEY `idx_todo_due_date` (`due_date`),
  KEY `idx_todo_user_status` (`user_id`,`status`),
  KEY `idx_todo_user_priority` (`user_id`,`priority`),
  KEY `idx_todo_user_due_date` (`user_id`,`due_date`),
  CONSTRAINT `fk_todo_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='待办事项表';
/*!40101 SET character_set_client = @saved_cs_client */;

