INSERT INTO `todotask` VALUES (1,15,'BK-101井GR曲线重构验证','验证BK-101井深度500-600m的GR曲线重构结果，对比原始数据误差率需≤2%',0,1,'2026-02-10 18:00:00','曲线重构',NULL,'2026-02-01 09:30:00','2026-02-03 16:09:48'),(2,15,'LD-205井电阻率数据质量检查','检查LD-205井全井段电阻率曲线数据完整性，修复异常值和缺失点',1,1,'2026-02-15 12:00:00','数据检查','2026-02-02 23:35:07','2026-02-03 10:15:00','2026-02-02 23:35:07'),(3,15,'V3.0重构模型参数调优','调整深度学习模型的学习率和迭代次数，提升曲线重构准确率至96.8%',0,2,'2026-02-05 20:00:00','模型优化',NULL,'2026-01-28 14:20:00','2026-02-03 16:09:11'),(4,15,'XC-308井密度曲线分析报告','生成XC-308井密度曲线重构分析报告，包含误差分析和可视化图表',1,1,'2026-02-20 17:00:00','报告生成','2026-02-02 23:35:08','2026-02-02 11:00:00','2026-02-02 23:35:08'),(5,15,'NJ-412井测井数据批量导入','批量导入NJ-412井2026年1月测井原始数据，格式为CSV',0,2,'2026-02-03 15:00:00','数据导入',NULL,'2026-01-30 08:45:00','2026-02-03 16:09:47'),(6,15,'SY-506井声波曲线重构','对SY-506井深度1000-2000m声波曲线进行重构，使用V3.0模型',1,1,'2026-02-12 10:00:00','曲线重构','2026-02-02 23:35:06','2026-02-02 14:00:00','2026-02-02 23:35:06'),(8,15,'曲线重构模型鲁棒性测试','测试V3.0模型对异常数据的鲁棒性，模拟10%噪声数据验证效果',1,0,'2026-02-25 18:00:00','模型优化','2026-02-02 23:35:09','2026-02-02 09:00:00','2026-02-02 23:35:09'),(9,15,'2月测井曲线重构汇总报告','汇总2026年2月所有井的曲线重构结果，统计准确率和完成率',0,1,'2026-02-05 12:00:00','报告生成',NULL,'2026-02-03 10:00:00','2026-02-03 15:10:27'),(10,12,'测井数据系统备份','备份2026年1-2月所有测井重构数据，存储至离线服务器',0,2,'2026-02-08 20:00:00','系统维护','2026-02-03 14:44:11','2026-02-03 16:00:00','2026-02-02 16:00:00'),(14,15,'完成Well-A1井储层评价报告（dataset-2026-1）','基于测井曲线（AC、DEN、RT、GR）对dataset-2026-1的Well-A1井2100-2120m井段进行储层评价，识别油气层位，计算孔隙度和饱和度，提交评价报告。',1,2,'2026-02-02 22:00:27','储层评价','2026-02-03 20:00:27','2026-01-29 22:00:27','2026-02-03 22:00:27'),(15,15,'Well-B2井CNL预测数据验证（dataset-2026-2）','对比dataset-2026-2的AI预测CNL曲线与实验室岩心分析数据，验证预测精度，误差超过5%的深度点需要标记并分析原因。',0,2,'2026-02-05 22:00:27','曲线重构',NULL,'2026-02-01 22:00:27','2026-02-01 22:00:27'),(16,15,'处理Well-B2井井径异常数据（dataset-2026-2）','dataset-2026-2的Well-B2井深度1864-1866m处井径扩大至10.5英寸以上，需进行井眼环境校正，重新计算密度孔隙度，确保后续CNL预测输入数据质量。',0,1,'2026-02-06 22:00:27','测井数据检查',NULL,'2026-02-02 22:00:27','2026-02-02 22:00:27'),(17,15,'Well-C3井气层识别与评价（dataset-2026-3）','dataset-2026-3的Well-C3井1950-1970m深度段显示高阻（RT>350Ω·m）、低DEN（2.32-2.39）特征，疑似气层，需结合CNL预测结果进行流体性质判别。',0,2,'2026-02-07 22:00:27','储层评价',NULL,'2026-02-01 22:00:27','2026-02-01 22:00:27'),(18,15,'Well-D4井复杂岩性处理（dataset-2026-4）','dataset-2026-4的Well-D4井2200-2220m存在薄互层特征，需进行曲线平滑和层序划分，提高CNL预测精度。',0,1,'2026-02-08 22:00:27','测井数据检查',NULL,'2026-01-31 22:00:27','2026-01-31 22:00:27'),(19,15,'更新测井解释模型参数','根据最新的岩心刻度数据，调整砂岩储层的m、n、a、b等阿尔奇公式参数，更新解释模型以提高含水饱和度计算精度。',0,1,'2026-02-09 22:00:27','模型优化',NULL,'2026-01-31 22:00:27','2026-01-31 22:00:27'),(20,15,'导入Well-E5井新数据（创建dataset-2026-5）','将Well-E5井2100-2300m井段的LAS格式测井数据导入系统，创建新的dataset-2026-5数据集，进行数据质量检查和深度校正。',0,0,'2026-02-10 22:00:27','测井数据检查',NULL,'2026-01-30 22:00:27','2026-01-30 22:00:27'),(21,15,'审核dataset-2026-1至dataset-2026-4解释成果','审核四个数据集的测井解释成果图，检查层位划分、参数取值和成果图件规范性，确保符合行业标准。',1,1,'2026-02-01 22:00:27','团队管理','2026-02-04 19:54:23','2026-01-28 22:00:27','2026-02-04 19:54:23'),(22,15,'参加储量计算技术研讨会','参加周五下午的储量计算技术研讨会，准备dataset-2026-1至dataset-2026-4的储量计算案例分享材料。',0,2,'2026-02-04 22:00:27','会议培训',NULL,'2026-02-02 22:00:27','2026-02-02 22:00:27');
/*!40000 ALTER TABLE `todotask` ENABLE KEYS */;
